"""B-roll generated by Google's Gemini Omni Flash 1.1, served by fal.ai.

One clip per script beat, from that beat's `broll_query`. This replaces stock footage
(Pexels, free) with footage made for the story — at $0.03 per generated second, so a
video's B-roll is roughly $0.75-$1.35 instead of $0.

fal's queue API (verified against fal's OpenAPI for this endpoint):
  POST  https://queue.fal.run/<endpoint>                      -> {request_id, ...}
  GET   https://queue.fal.run/<endpoint>/requests/<id>/status -> {status: IN_QUEUE|IN_PROGRESS|COMPLETED}
  GET   https://queue.fal.run/<endpoint>/requests/<id>        -> {video: {url}}
Auth header is `Authorization: Key <key>`.  Inputs: prompt, aspect_ratio (16:9|9:16),
duration (3-10 s integer), resolution (360p|720p|1080p|4k).

NOT verified end-to-end: the account balance was exhausted when this was written, so no
clip has actually been generated. Everything fails soft — any problem logs a warning and
returns None, and the renderer falls back to the hero card for that beat.
"""
from __future__ import annotations

import hashlib
import logging
import math
import time
from pathlib import Path
from typing import Callable

import httpx

from app.providers.base import BrollClip, BrollProvider, BrollRequest
from app.settings import get_settings

log = logging.getLogger(__name__)

QUEUE_ROOT = "https://queue.fal.run"
MIN_SECONDS, MAX_SECONDS = 3, 10          # the endpoint's accepted duration range
STYLE_SUFFIX = ("Cinematic documentary B-roll, realistic, smooth camera motion, no on-screen "
                "text, no watermarks, no brand logos other than the story's own subject, "
                "no recognizable real people.")


def clamp_duration(seconds: float) -> int:
    """Whole seconds in the endpoint's 3-10 range. Rounds up so we never under-shoot a
    beat; the renderer freezes the last frame if a beat is longer than 10 s."""
    return max(MIN_SECONDS, min(MAX_SECONDS, math.ceil(seconds)))


def build_prompt(query: str, context: str = "") -> str:
    story = f' Footage for a news story titled "{context.strip()}".' if context.strip() else ""
    return f"{query.strip().rstrip('.')}.{story} {STYLE_SUFFIX}"


class FalBroll(BrollProvider):
    name = "fal_gemini_omni"
    max_clip_seconds = MAX_SECONDS

    def __init__(self, cfg: dict, client: httpx.Client | None = None,
                 sleep: Callable[[float], None] = time.sleep):
        self.endpoint = cfg.get("endpoint", "google/gemini-omni-flash/v1.1/text-to-video")
        self.resolution = cfg.get("resolution", "720p")
        self.poll_seconds = float(cfg.get("poll_seconds", 5))
        self.max_wait_seconds = float(cfg.get("max_wait_seconds", 300))
        self._client = client or httpx.Client(timeout=60.0)
        self._sleep = sleep
        self._disabled = False      # set once the account is locked, so later beats skip

    def _headers(self) -> dict:
        return {"Authorization": f"Key {get_settings().fal_key}"}

    def _cache_key(self, prompt: str) -> str:
        return hashlib.sha1(f"{self.endpoint}|{self.resolution}|{prompt}".encode()).hexdigest()[:12]

    def _cached(self, out_dir: Path, prompt: str, need: int) -> Path | None:
        """A clip already generated for this exact prompt that is long enough. Generating
        costs $0.03/s, so a re-render (new voice, caption tweak) must not pay again."""
        best: tuple[int, Path] | None = None
        for f in (out_dir / "fal_cache").glob(f"{self._cache_key(prompt)}_*s.mp4"):
            try:
                dur = int(f.stem.rsplit("_", 1)[1].rstrip("s"))
            except ValueError:
                continue
            if dur >= need and (best is None or dur < best[0]):
                best = (dur, f)
        return best[1] if best else None

    def _fail(self, what: str, resp: httpx.Response) -> None:
        text = resp.text[:300]
        log.warning("fal %s failed (HTTP %s): %s", what, resp.status_code, text)
        if resp.status_code == 403 and ("locked" in text.lower() or "balance" in text.lower()):
            self._disabled = True
            log.warning("fal account has no balance — skipping generated B-roll for the rest "
                        "of this video. Top up at fal.ai/dashboard/billing")

    def fetch(self, req: BrollRequest, out_dir: Path) -> BrollClip | None:
        if self._disabled:
            return None
        if not get_settings().fal_key:
            log.warning("FAL_KEY not set — no generated B-roll")
            return None

        prompt = build_prompt(req.query, req.context)
        duration = clamp_duration(req.seconds)
        hit = self._cached(out_dir, prompt, duration)
        if hit is not None:
            log.info("fal B-roll cache hit for %r — no charge", req.query)
            return BrollClip(hit, True, req.query,
                             attribution="Generated by Gemini Omni (Google) via fal.ai")

        body = {
            "prompt": prompt,
            "aspect_ratio": "9:16",
            "duration": duration,
            "resolution": self.resolution,
        }
        base = f"{QUEUE_ROOT}/{self.endpoint}"
        try:
            sub = self._client.post(base, json=body, headers=self._headers())
            if sub.status_code >= 400:
                self._fail("submit", sub)
                return None
            job = sub.json()
            request_id = job["request_id"]
            status_url = job.get("status_url") or f"{base}/requests/{request_id}/status"
            result_url = job.get("response_url") or f"{base}/requests/{request_id}"

            deadline = time.monotonic() + self.max_wait_seconds
            while True:
                st = self._client.get(status_url, headers=self._headers())
                if st.status_code >= 400:
                    self._fail("status", st)
                    return None
                if st.json().get("status") == "COMPLETED":
                    break
                if time.monotonic() > deadline:
                    log.warning("fal job %s still running after %ss — giving up on this beat",
                                request_id, self.max_wait_seconds)
                    return None
                self._sleep(self.poll_seconds)

            res = self._client.get(result_url, headers=self._headers())
            if res.status_code >= 400:
                self._fail("result", res)
                return None
            url = res.json()["video"]["url"]

            (out_dir / "fal_cache").mkdir(parents=True, exist_ok=True)
            target = out_dir / "fal_cache" / f"{self._cache_key(prompt)}_{duration}s.mp4"
            dl = self._client.get(url, follow_redirects=True)
            dl.raise_for_status()
            target.write_bytes(dl.content)
        except (httpx.HTTPError, KeyError, ValueError) as exc:
            log.warning("fal B-roll failed for %r: %s", req.query, exc)
            return None

        return BrollClip(target, True, req.query,
                         attribution="Generated by Gemini Omni (Google) via fal.ai")
